import{_ as a,o as t,c as r,a5 as s}from"./chunks/framework.DrDMl0tG.js";const o="/assets/voxel_map_ray_casting.Cn8O6oy_.png",m=JSON.parse('{"title":"Server Example: Voxel Map Ray Casting","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/voxel_map_ray_casting.md","filePath":"sections/examples/server/voxel_map_ray_casting.md"}'),i={name:"sections/examples/server/voxel_map_ray_casting.md"};function l(n,e,c,d,h,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="server-example-voxel-map-ray-casting" tabindex="-1">Server Example: Voxel Map Ray Casting <a class="header-anchor" href="#server-example-voxel-map-ray-casting" aria-label="Permalink to &quot;Server Example: Voxel Map Ray Casting&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Scans a voxel map with a spinning lidar and a single probe ray. The map holds rolling hills, a hut with a door, an arch and a tunnel through a hill, so the scan shows overhangs and hollow spaces that a height map cannot represent. Use <code>rayrai_tcp_viewer</code> for supported visualization.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+o+'" alt="voxel_map_ray_casting example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>voxel_map_ray_casting</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/voxel_map_ray_casting</span></span></code></pre></div><p>On Windows, run <code>voxel_map_ray_casting.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Builds a 30 m x 30 m map of 0.1 m voxels with <code>World::addVoxelMap()</code> and <code>VoxelMap::fillBox()</code>, then carves the hut&#39;s interior, its door and the tunnel out of the solid.</li><li>A lidar of 32 x 512 rays drives along a circle 1.2 m above the terrain and scans it every step with <code>World::rayTestLidar()</code>; the hits are drawn as a point cloud colored by range.</li><li>A probe ray sweeps the scene from above with <code>World::rayTest()</code>; a red line and a sphere mark where it hits the first occupied voxel.</li><li>See <a href="./../../VoxelMap.html">Voxel Map</a>.</li></ul>',13)])])}const x=a(i,[["render",l]]);export{m as __pageData,x as default};
